draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // introvert world
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/4, H/2, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();

  // introvert
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 25);
  ctx.lineTo(W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 - 15, H/2 + 37);
  ctx.lineTo(W/4 + 15, H/2 + 37);
  ctx.stroke();

  // extrovert world
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 50 + 20*Math.cos(t), 0, 2*Math.PI);
  ctx.stroke();

  // extrovert
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 25);
  ctx.lineTo(W - W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 - 15, H/2 + 37);
  ctx.lineTo(W - W/4 + 15, H/2 + 37);
  ctx.stroke();

  // connection
  ctx.beginPath();
  ctx.moveTo(W/2 - 25 + 10*Math.sin(t), H/2);
  ctx.lineTo(W/2 + 25 + 10*Math.cos(t), H/2);
  ctx.stroke();

  ctx.restore();
}
